  &reftitle.description;

   trueuasort
   arrayarray
   callablecallback


user-defined comparison function प्रयोग गरेर array लाई in place sort गर्दछ, जसले गर्दा यसका keys ले आफूसँग सम्बन्धित values सँगको correlation कायम राख्दछन्।

यो मुख्यतया त्यस्ता associative arrays sort गर्दा प्रयोग गरिन्छ, जहाँ वास्तविक element को क्रम महत्त्वपूर्ण हुन्छ।
  &note.sort-unstable;
  &note.reset-index;

  &reftitle.examples;



    uasort को आधारभूत उदाहरण


<?php
// Comparison function
function cmp($a, $b) {
    if ($a == $b) {
        return 0;
    }
    return ($a < $b) ? -1 : 1;
}

// Array to be sorted
$array = array('a' => 4, 'b' => 8, 'c' => -1, 'd' => -9, 'e' => 2, 'f' => 5, 'g' => 3, 'h' => -4);
print_r($array);

// Sort and print the resulting array
uasort($array, 'cmp');
print_r($array);
?>


